/**
 * O vazio do átomo — a bola de tênis e o elétron a três quilômetros.
 *
 * A comparação do artigo é boa justamente porque não cabe na página: se o núcleo
 * fosse uma bola de tênis, o elétron giraria a uns 3 km dali, e entre os dois não
 * haveria absolutamente nada. A cena não tenta desenhar isso em escala — seria um
 * pixel e um vazio —, ela desenha a RÉGUA: a bola no zero, marcos de cem em cem
 * metros, a faixa do alvo, e o elétron onde o slider o pôs.
 *
 * A leitura da fração de volume (1 parte em 10^n) fica embaixo, porque é a
 * consequência da distância, e não outra coisa para ajustar.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import {
  disco,
  type EstadoDaViz,
  etiqueta,
  infoDe,
  limitar,
  numeroDe,
  paleta,
  ptBR,
  retangulo,
  rodape,
  texto,
  titulo,
} from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

const CAMPO = '#cfe3c9';
const BOLA = '#d8e04a';

const atomo: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number, t: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const valores = (estado.valores ?? {}) as Readonly<Record<string, unknown>>;

    const d = Math.max(0, numeroDe(valores, 'd', 0));
    const alvo = numeroDe(info, 'alvo', 3000);
    const expoente = Math.round(numeroDe(info, 'exp', 0));
    const raioCm = numeroDe(info, 'raioCm', 3.5);
    const ok = info.ok === true;
    const tinta = ok ? cor.verde : cor.azul;
    const miudo = limitar(A * 0.032, 8, 11);

    titulo(ctx, L, A, 'Entre o núcleo e o elétron não há nada');

    // ── O terreno ─────────────────────────────────────────────────────────
    const x0 = L * 0.09;
    const x1 = L * 0.93;
    const chao = A * 0.62;
    const teto = 5000;

    ctx.fillStyle = CAMPO;
    ctx.fillRect(0, chao, L, A * 0.14);

    const px = (metros: number): number => x0 + (limitar(metros, 0, teto) / teto) * (x1 - x0);

    // A régua, com marcos de mil em mil metros.
    ctx.strokeStyle = cor.fraco;
    ctx.lineWidth = 1.6;
    ctx.beginPath();
    ctx.moveTo(x0, chao);
    ctx.lineTo(x1, chao);
    ctx.stroke();

    for (let m = 0; m <= teto; m += 1000) {
      ctx.strokeStyle = cor.trilho;
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(px(m), chao - 5);
      ctx.lineTo(px(m), chao + 5);
      ctx.stroke();
      texto(ctx, m === 0 ? '0' : `${m / 1000} km`, px(m), chao + miudo * 1.7, miudo * 0.9, {
        cor: cor.fraco,
        peso: 600,
      });
    }

    // A faixa do alvo — onde o elétron de fato estaria.
    const tolerancia = 150;
    retangulo(
      ctx,
      px(alvo - tolerancia),
      chao - A * 0.13,
      px(alvo + tolerancia) - px(alvo - tolerancia),
      A * 0.13,
      3,
      'rgb(47 143 92 / 20%)',
    );
    etiqueta(ctx, `alvo ${ptBR(alvo)} m`, px(alvo), chao - A * 0.155, miudo, cor.verde, 700);

    // ── A bola de tênis, no zero ──────────────────────────────────────────
    const raioBola = Math.max(7, A * 0.038);
    disco(ctx, px(0) + 1.5, chao - raioBola + 2, raioBola, 'rgb(35 42 85 / 25%)');
    disco(ctx, px(0), chao - raioBola, raioBola, BOLA);
    ctx.strokeStyle = '#8b9130';
    ctx.lineWidth = 1.4;
    ctx.beginPath();
    ctx.arc(px(0) - raioBola * 0.5, chao - raioBola, raioBola * 1.1, -0.9, 0.9);
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(px(0) + raioBola * 0.5, chao - raioBola, raioBola * 1.1, Math.PI - 0.9, Math.PI + 0.9);
    ctx.stroke();

    etiqueta(
      ctx,
      `núcleo: bola de ${raioCm.toFixed(1).replace('.', ',')} cm`,
      px(0),
      chao + miudo * 3.4,
      miudo,
      cor.texto,
      700,
      { alinhamento: 'left' },
    );

    // ── O elétron, onde o slider o pôs ────────────────────────────────────
    const xEletron = px(d);
    const alturaOrbita = A * 0.07;
    const yEletron = chao - raioBola - alturaOrbita + Math.sin(t * 3) * 3;

    // A órbita insinuada: um arco que sai da bola e passa pelo elétron.
    ctx.strokeStyle = tinta;
    ctx.lineWidth = 1.2;
    ctx.setLineDash([3, 5]);
    ctx.globalAlpha = 0.6;
    ctx.beginPath();
    ctx.ellipse(px(0), chao - raioBola, Math.max(6, xEletron - px(0)), alturaOrbita, 0, Math.PI, 0);
    ctx.stroke();
    ctx.globalAlpha = 1;
    ctx.setLineDash([]);

    disco(ctx, xEletron, yEletron, Math.max(3.5, A * 0.016), tinta);
    etiqueta(
      ctx,
      `elétron · ${ptBR(Math.round(d))} m`,
      xEletron,
      yEletron - miudo * 1.8,
      miudo,
      tinta,
      800,
    );

    // ── A consequência ────────────────────────────────────────────────────
    texto(
      ctx,
      expoente > 0
        ? `o núcleo ocupa 1 parte em 10^${expoente} do volume`
        : 'aproxime o elétron e a conta aparece',
      L / 2,
      A * 0.87,
      miudo * 1.15,
      { cor: ok ? cor.verde : cor.fraco, peso: 800 },
    );

    rodape(
      ctx,
      L,
      A,
      ok,
      'O átomo é quase todo VAZIO ✔',
      d < alvo
        ? 'Perto demais: multiplique o raio do núcleo pela razão do átomo.'
        : 'Longe demais: refaça a conta.',
    );
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A, t }) => desenhar(ctx, L, A, t),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default atomo;
